SELECT c.id, c.book_id, c.user_id, c.content, c.parent_id, c.create_time, b.book_name, u.nick_name FROM book_comment c LEFT JOIN book_info b ON b.id = c.book_id LEFT JOIN user_info u ON u.id = c.user_id
(c.content LIKE CONCAT('%', #{keyword}, '%') OR b.book_name LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.create_time DESC, c.id DESC LIMIT #{offset}, #{limit}

